"""AgentLink live dashboard — served by the relay process.

Security model (owner spec):
* ONE-TIME login with the operator password. On success the server
  issues a trusted-device token; only its SHA-256 hash is stored.
* The cookie is HttpOnly (+ Secure behind HTTPS), SameSite=Lax, and the
  session persists for 7 DAYS, then one fresh login is needed.
* Sessions are revocable (logout revokes server-side immediately).
* Login attempts are rate-limited per IP.
* Content: the relay itself stores ciphertext only (E2EE). With the
  owner's OVERSIGHT key configured (AGENTLINK_OVERSIGHT_KEY_FILE),
  the dashboard opens the oversight copy of content server-side —
  message text, work content, and (via /api/blob) file bytes — for
  the authenticated operator session only; the relay's stored rows
  stay ciphertext, and content that fails to open stays sealed.

Real-time: /api/stream is a Server-Sent Events push channel — the page
updates the moment anything happens, no refresh, no polling — and key
events (work assigned/delivered/completed, agents coming online) fire
browser notifications.
"""

from __future__ import annotations

import base64
import hashlib
import hmac
import json
import logging
import os
import queue
import secrets
import threading
import time
import urllib.parse
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

log = logging.getLogger("agentlink.dashboard")

from .timing import DEVICE_TRUST_SECONDS

SESSION_TTL = DEVICE_TRUST_SECONDS  # 7 days — see agentlink/timing.py
COOKIE = "agentlink_dash"
MAX_FAILURES = 5
FAILURE_WINDOW = 300  # seconds
# Snapshot cache TTL (v1.1.4): /api/status and the /api/stream connect
# snapshot serve the cached payload immediately and revalidate in the
# background once it is older than this. State changes already arrive
# via notify() (coalesced rebuild ≤1s), so the TTL is only a backstop;
# the SSE stream corrects any first-paint staleness live.
SNAPSHOT_TTL = 5.0  # seconds
# Bounded wait (v1.1.4.1): a read that arrives AFTER a notify() must
# never be served a snapshot that predates that notify — it waits for
# the coalesced build covering it, at most this long, then serves the
# newest cache regardless (a request must never hang forever).
SNAPSHOT_WAIT = 15.0  # seconds


def _hash(token: str) -> str:
    return hashlib.sha256(token.encode()).hexdigest()


def _load_oversight_identity():
    """Owner-oversight key: when AGENTLINK_OVERSIGHT_KEY_FILE names a
    readable key file, the dashboard opens the oversight copy of
    conversation content SERVER-SIDE, for the authenticated operator
    session only. Accepted file shapes: an agent-style keys JSON
    ({"private_key": <b64>}), a bare base64 or hex X25519 private key,
    or the raw 32 key bytes. Returns None when unset or unreadable —
    the chat view then degrades honestly to envelope-only."""
    path = os.environ.get("AGENTLINK_OVERSIGHT_KEY_FILE", "").strip()
    if not path:
        return None
    try:
        raw = Path(path).read_bytes()
        priv = None
        try:
            priv = base64.b64decode(json.loads(raw)["private_key"])
        except Exception:
            pass
        if priv is None or len(priv) != 32:
            s = raw.strip()
            cands = []
            try:
                cands.append(base64.b64decode(s, validate=True))
            except Exception:
                pass
            try:
                cands.append(bytes.fromhex(s.decode()))
            except Exception:
                pass
            if len(s) == 32:
                cands.append(s)
            priv = next((c for c in cands if len(c) == 32), None)
        if priv is None:
            raise ValueError("no 32-byte X25519 private key in file")
        from cryptography.hazmat.primitives.asymmetric.x25519 import (
            X25519PrivateKey)
        from .crypto import Identity
        ident = Identity.__new__(Identity)
        ident.username = "oversight"
        ident.path = None
        ident._priv = X25519PrivateKey.from_private_bytes(priv)
        ident._sign = None
        log.info("oversight key loaded from %s", path)
        return ident
    except Exception:
        log.warning("oversight key not loaded from %s", path, exc_info=True)
        return None


class DashboardServer:
    def __init__(self, relay, host: str, port: int, password: str):
        self.relay = relay
        self.host = host
        self.port = port
        self._password = password
        self._subscribers: set[queue.Queue] = set()
        self._lock = threading.Lock()
        self._dirty = False
        self._builder: threading.Thread | None = None
        # Backend watch (v1.3.4): the newest store digest this
        # dashboard has already reflected. Changes on OTHER servers
        # (presence flips, migrations, registry moves) raise no
        # local notify(); the digest is how the push loop learns
        # about them. None = not primed yet.
        self._last_digest: str | None = None
        # Snapshot cache (v1.1.4, stale-while-revalidate): the exact
        # JSON string _build_snapshot produces, kept server-side so a
        # cold /api/status or /api/stream connect answers immediately
        # instead of paying a full store scan (measured 6–11s against
        # the Supabase-backed store) on every first paint. Only
        # complete JSON strings are ever published, under the lock —
        # a half-built snapshot can never be served. Freshness stays
        # honest: notify() rebuilds within ~1s of any real event and
        # pushes over SSE; the cache only spares duplicate builds.
        # Read contract (v1.1.4.1): staleness is tolerated ONLY for
        # TTL expiry — a read that arrives after a notify() is never
        # served a snapshot that predates that notify; it waits
        # (bounded by SNAPSHOT_WAIT) for the build covering it.
        # _event_seq counts notify() calls; _built_event_seq is the
        # event count the cached snapshot covers.
        self._snap_lock = threading.Lock()
        self._snap_cond = threading.Condition(self._snap_lock)
        self._snap_json: str | None = None
        self._snap_at = 0.0  # time.monotonic() when _snap_json was built
        self._builds = 0     # completed snapshot builds (tests, doctor)
        self._event_seq = 0
        self._built_event_seq = 0
        self._failures: dict[str, list[float]] = {}
        self._oversight = _load_oversight_identity()
        # Oversight-unwrapped file keys, learned while opening
        # conversation items in _serve_data: blob_id -> {key, nonce,
        # mime, name, kind}. Lets /api/blob/<id> serve decrypted file
        # bytes to the operator session WITHOUT ever putting file
        # bytes (or keys) into the /api/status JSON.
        self._blob_files: dict[str, dict] = {}
        self._blob_lock = threading.Lock()
        # Owner downloads (v1.1.2): library-id -> resolved download
        # source ({"mode": "inline", "ov": wrap} or {"mode": "blob",
        # "descriptor": desc}) or None for a KNOWN-unresolvable
        # (legacy, pre-oversight) entry. Resolved while annotating
        # _serve_data; the download route re-derives bytes on demand
        # — file bytes are never cached here and never enter the
        # /api/status JSON.
        self._library_src: dict[str, dict | None] = {}
        self._server: ThreadingHTTPServer | None = None
        self._thread: threading.Thread | None = None

    # -- lifecycle ---------------------------------------------------------
    def start(self) -> "DashboardServer":
        handler = self._make_handler()
        self._server = ThreadingHTTPServer((self.host, self.port), handler)
        self._server.daemon_threads = True
        self.port = self._server.server_address[1]
        self._thread = threading.Thread(target=self._server.serve_forever,
                                        daemon=True)
        self._thread.start()
        log.info("dashboard listening on %s:%s", self.host, self.port)
        # Warm the snapshot cache in the background (v1.1.4): the
        # first build still costs a full store scan, but it happens
        # once at boot — not inside the operator's first page load.
        # notify() starts the coalesced builder thread, which builds
        # within ~1s and publishes into the cache.
        self.notify()
        return self

    def stop(self) -> None:
        if self._server is not None:
            self._server.shutdown()
            self._server = None

    # -- push ----------------------------------------------------------------
    def notify(self) -> None:
        # Coalesced snapshot builds (production fix, 2026-11-02): the
        # snapshot is a full store scan. Building it synchronously in
        # the caller's thread — often the relay event loop, via
        # _log_activity — stalls agent traffic for the whole build on
        # a network-backed store (hundreds of round trips). Builds now
        # run on a dedicated thread, at most once per second, only
        # when something changed; subscribers still get pushed fresh
        # snapshots, and every build also publishes the cached
        # snapshot /api/status serves (v1.1.4).
        with self._lock:
            self._dirty = True
            if self._builder is None:
                self._builder = threading.Thread(
                    target=self._build_loop, daemon=True)
                self._builder.start()
        # Sequence every signalled change (separate lock, taken after
        # _lock is released — the two are never held together): reads
        # compare this against the sequence the cache covers.
        with self._snap_lock:
            self._event_seq += 1

    def _push(self, snapshot: str) -> None:
        with self._lock:
            subs = list(self._subscribers)
        for q in subs:
            try:
                q.put_nowait(snapshot)
            except queue.Full:
                pass

    def _backend_digest(self) -> str | None:
        fn = getattr(getattr(self, "relay", None),
                     "_backend_digest", None)
        if fn is None:
            return None
        try:
            return fn()
        except Exception:
            return None

    def _build_loop(self) -> None:
        while True:
            built = False
            with self._lock:
                dirty = self._dirty
                self._dirty = False
            if dirty:
                with self._snap_lock:
                    seq = self._event_seq
                try:
                    snapshot = self._build_snapshot(seq)
                except Exception:
                    snapshot = None
                if snapshot is not None:
                    built = True
                    self._push(snapshot)
            # Backend watch (v1.3.4): a change on ANOTHER server —
            # an agent's presence flipping on its own server, a
            # migration home, a registry move — produces no local
            # event, so the serving relay never calls notify() and
            # an open page would sit on a stale truth until reload.
            # The store's digest is the shared change signal: when
            # it moves, rebuild and push. Presence on the dashboard
            # is then real-time BACKEND-WIDE, not just for events
            # this relay happened to witness.
            digest = self._backend_digest()
            if digest is not None:
                if built or self._last_digest is None:
                    self._last_digest = digest
                elif digest != self._last_digest:
                    self._last_digest = digest
                    with self._snap_lock:
                        seq = self._event_seq
                    try:
                        snapshot = self._build_snapshot(seq)
                    except Exception:
                        snapshot = None
                    if snapshot is not None:
                        self._push(snapshot)
            time.sleep(1.0)

    # -- snapshot cache (stale-while-revalidate, v1.1.4) ------------------
    def _build_snapshot(self, start_seq: int | None = None) -> str:
        """Build the dashboard payload once and atomically publish it
        as the cached snapshot. The JSON string is complete before it
        is stored, so readers only ever see whole snapshots.
        start_seq is the notify() sequence the build started under;
        publishing records that the cache covers it and wakes any
        reader waiting for a post-notify snapshot."""
        if start_seq is None:
            with self._snap_lock:
                start_seq = self._event_seq
        snapshot = json.dumps(self._serve_data())
        with self._snap_cond:
            self._snap_json = snapshot
            self._snap_at = time.monotonic()
            self._builds += 1
            if start_seq > self._built_event_seq:
                self._built_event_seq = start_seq
            self._snap_cond.notify_all()
        return snapshot

    def _snapshot_json(self) -> str:
        """The payload for /api/status and the /api/stream connect
        snapshot. Serves the cache immediately when it covers every
        change signalled before this read arrived; a TTL-stale cache
        (> SNAPSHOT_TTL) is served too and revalidated in the
        background via the same coalesced builder notify() drives
        (the SSE push then corrects the open page live). If a change
        WAS signalled (notify) but its build has not published yet,
        the read waits for that build — bounded by SNAPSHOT_WAIT —
        rather than answering with a snapshot that predates a change
        the server already knows about. Only with no snapshot at all
        — cold start, warmup still running — does the caller pay a
        synchronous build, exactly as before the cache."""
        with self._snap_cond:
            seq = self._event_seq
            deadline = time.monotonic() + SNAPSHOT_WAIT
            while self._snap_json is not None \
                    and self._built_event_seq < seq \
                    and time.monotonic() < deadline:
                self._snap_cond.wait(timeout=0.25)
            snap = self._snap_json
            at = self._snap_at
        if snap is not None:
            if time.monotonic() - at > SNAPSHOT_TTL:
                self.notify()
            return snap
        return self._build_snapshot()

    # -- owner oversight: open sealed content for the operator session --
    # The protocol emits exactly ONE wrap shape (crypto.encrypt_to_
    # pubkey envelope {v, alg, eph_pub, nonce, ct}) plus a `kind`:
    #   kind "content"     — the envelope seals the content payload
    #                        JSON itself (1:1 messages, work content).
    #   kind "content_key" — the envelope seals a raw symmetric key
    #                        (group/channel key, or a file key); the
    #                        content itself travels in a sibling
    #                        envelope under that key.
    def _oversight_open(self, ov, content_envelope=None) -> bytes | None:
        """Open one item's oversight wrap to CONTENT plaintext bytes.

        kind "content" (or a kind-less envelope): decrypt the wrap
        directly. kind "content_key": unwrap the symmetric key, then
        decrypt the item's persisted content envelope
        ({epoch, nonce, ct}) with it — the raw key bytes themselves
        are NEVER returned as content. Any failure returns None (the
        item stays sealed) — content is never guessed or faked."""
        ident = self._oversight
        if ident is None or not isinstance(ov, dict):
            return None
        try:
            from .crypto import decrypt_with_key
            if ov.get("kind") == "content_key":
                if not isinstance(content_envelope, dict):
                    return None
                key = ident.decrypt_envelope(ov)
                return decrypt_with_key(key, content_envelope)
            if isinstance(ov.get("wrapped_key"), dict):
                # Legacy fabricated shape (pre-composition tests):
                # content key wrapped under `wrapped_key`, content in
                # nonce/ciphertext fields. Kept for unit coverage of
                # the opener only — production clients never emit it.
                key = ident.decrypt_envelope(ov["wrapped_key"])
                return decrypt_with_key(key, {
                    "nonce": ov.get("nonce", ""),
                    "ct": ov.get("ciphertext") or ov.get("ct") or ""})
            if ov.get("eph_pub"):
                return ident.decrypt_envelope(ov)
        except Exception:
            return None
        return None

    def _oversight_open_key(self, ov) -> bytes | None:
        """Unwrap a kind "content_key" oversight wrap to its raw
        symmetric key bytes (used for FILE keys from a message's file
        descriptor — the key feeds /api/blob decryption, it is never
        rendered or serialised). Any other shape returns None."""
        ident = self._oversight
        if ident is None or not isinstance(ov, dict):
            return None
        if ov.get("kind") != "content_key":
            return None
        try:
            return ident.decrypt_envelope(ov)
        except Exception:
            return None

    @staticmethod
    def _content_fields(plaintext: bytes):
        """Parse decrypted content plaintext into display fields.

        Content plaintexts are JSON OBJECTS: messages {"body",
        "kind", "file"}; work {"title", "instructions", ...} /
        {"body", ...} / {"note"}. Anything else — unparseable bytes,
        a raw symmetric key mis-decoded as text, a JSON scalar — is
        NOT content: returns None and the caller leaves the item
        sealed with no text field (honesty rule: undecodable content
        is never rendered as mojibake)."""
        try:
            obj = json.loads(plaintext)
        except Exception:
            return None
        if not isinstance(obj, dict):
            return None
        f = obj.get("file") if isinstance(obj.get("file"), dict) else {}
        text = obj.get("body") or obj.get("instructions") \
            or obj.get("note") or ""
        return {"text": text if isinstance(text, str) else str(text),
                "content_kind": obj.get("kind") or f.get("kind")
                or "text",
                "file_name": f.get("filename") or f.get("name") or "",
                "title": obj.get("title") or "",
                "obj": obj}

    def _register_blob(self, item: dict, obj: dict) -> None:
        """If an opened content object carries a blob file
        descriptor, expose the blob to the operator session: the
        item gains blob_id/file_mime (+ blob_url when the
        descriptor's own oversight wrap yields the file key), and
        the key+nonce are remembered server-side for /api/blob.
        File BYTES never enter the status payload."""
        f = obj.get("file") if isinstance(obj, dict) else None
        if not isinstance(f, dict):
            return
        blob_id = f.get("blob_id")
        if not blob_id:
            return
        item["blob_id"] = blob_id
        item["file_mime"] = f.get("mime") or "application/octet-stream"
        key = self._oversight_open_key(f.get("oversight"))
        if key is None or not f.get("blob_nonce"):
            return
        entry = {"key": key, "nonce": f["blob_nonce"],
                 "mime": item["file_mime"],
                 "name": f.get("name") or f.get("filename") or "",
                 "kind": f.get("kind") or ""}
        with self._blob_lock:
            self._blob_files[blob_id] = entry
            while len(self._blob_files) > 512:  # FIFO cap
                self._blob_files.pop(next(iter(self._blob_files)))
        item["blob_url"] = f"/api/blob/{blob_id}"

    def _blob_bytes(self, blob_id: str):
        """Decrypt one registered blob for /api/blob: fetch the
        ciphertext from the relay's blob store and open it with the
        oversight-unwrapped file key. Returns (data, entry) or
        None when the blob is unknown/unregistered/unreadable."""
        with self._blob_lock:
            entry = self._blob_files.get(blob_id)
        if entry is None:
            return None
        store = getattr(self.relay, "blob_store", None)
        if store is None:
            return None
        try:
            ct = store.get(blob_id)
            from .crypto import decrypt_with_key
            data = decrypt_with_key(entry["key"], {
                "nonce": entry["nonce"],
                "ct": base64.b64encode(ct).decode()})
        except Exception:
            return None
        return data, entry

    # -- owner downloads: Library + Vault (v1.1.2) --------------------
    # The owner personally downloads deliverables and vault files
    # from the dashboard — a READ action inside his oversight (the
    # dashboard otherwise stays monitor-only). Two wrap chains:
    #   * Library: an entry is metadata only; its bytes ride the
    #     work delivery's content object ({"files": [payload...]}),
    #     oversight-wrapped kind "content" on the work_delivered
    #     audit row. A payload is either inline (data_b64) or a blob
    #     descriptor (blob_id + nested content_key oversight wrap).
    #   * Vault: the entry's stored descriptor IS a blob descriptor
    #     (blob_id + blob_nonce + nested content_key oversight wrap),
    #     attached by _make_blob_descriptor on every vault put.
    # Entries sealed before owner oversight existed have no usable
    # wrap: they render an honest not-downloadable state and the
    # routes refuse cleanly — never a dead button, never fake bytes.

    def _blob_descriptor_bytes(self, desc) -> bytes | None:
        """Fetch + decrypt blob bytes via a descriptor's nested
        oversight wrap (kind content_key -> file key)."""
        if not isinstance(desc, dict):
            return None
        key = self._oversight_open_key(desc.get("oversight"))
        if key is None or not desc.get("blob_nonce") \
                or not desc.get("blob_id"):
            return None
        store = getattr(self.relay, "blob_store", None)
        if store is None:
            return None
        try:
            ct = store.get(desc["blob_id"])
            from .crypto import decrypt_with_key
            return decrypt_with_key(key, {
                "nonce": desc["blob_nonce"],
                "ct": base64.b64encode(ct).decode()})
        except Exception:
            return None

    @staticmethod
    def _match_delivery_file(obj, entry) -> dict | None:
        """Find the delivery-content file backing a library entry:
        exact sha256 match wins; filename+size is the fallback."""
        if not isinstance(obj, dict):
            return None
        cands = []
        files = obj.get("files")
        if isinstance(files, list):
            cands.extend(f for f in files if isinstance(f, dict))
        single = obj.get("file")
        if isinstance(single, dict):
            cands.append(single)
        sha = entry.get("sha256") or ""
        name = entry.get("filename") or ""
        size = int(entry.get("size") or 0)
        for f in cands:
            if sha and f.get("sha256") == sha:
                return f
        for f in cands:
            if name and (f.get("name") == name
                         or f.get("filename") == name) \
                    and (not size or int(f.get("size") or 0) == size):
                return f
        return None

    def _targeted_audit_rows(self, data) -> list:
        """Audit rows for exactly the ids this payload references
        (conversation items, activity rows, library works) — the
        oversight fallback and library resolution fetch ONLY what
        they need, by id (v1.3.2). The pre-1.3.2 code scanned
        list_audit(500) — the newest 500 rows of every kind — so an
        older item's wrap fell out of the window and older library
        entries misreported themselves 'sealed before owner
        oversight' while their delivery rows sat intact in the
        store. Stub stores without the targeted fetch keep the old
        scan (test doubles only; shipped stores all have it)."""
        ids = []
        for c in data.get("conversations", []):
            for item in c.get("items", []):
                if item.get("id"):
                    ids.append(item["id"])
        for row in data.get("activity", []):
            if row.get("ref_id"):
                ids.append(row["ref_id"])
            if row.get("work_id"):
                ids.append(row["work_id"])
        for e in data.get("library", []):
            if e.get("work_id"):
                ids.append(e["work_id"])
        store = self.relay.store
        fetch = getattr(store, "audit_rows_for_ids", None)
        if fetch is not None:
            if not ids:
                return []
            try:
                return fetch(ids)
            except Exception:
                return []
        try:
            return store.list_audit(500)
        except Exception:
            return []

    def _audit_for_work(self, entry) -> list:
        """Every audit row for one library entry's work id (the
        delivery row carries the oversight wrap) — targeted, any
        age (v1.3.2)."""
        store = self.relay.store
        fetch = getattr(store, "audit_for_work", None)
        if fetch is not None:
            try:
                return fetch(entry.get("work_id") or "")
            except Exception:
                return []
        try:
            return store.list_audit(500)
        except Exception:
            return []

    def _library_source(self, entry, audit_rows=None):
        """Resolve a library entry to its download source, or None
        when no usable oversight chain exists. Cached per entry;
        a missing work_delivered row is NOT cached (the delivery
        audit row may land a beat after the library index)."""
        lid = entry.get("id") or ""
        if lid in self._library_src:
            return self._library_src[lid]
        if audit_rows is None:
            audit_rows = self._audit_for_work(entry)
        seen_delivery = False
        resolved = None
        for r in audit_rows:
            if not isinstance(r, dict) \
                    or r.get("kind") != "work_delivered" \
                    or r.get("work_id") != entry.get("work_id"):
                continue
            seen_delivery = True
            ov = r.get("oversight")
            if not isinstance(ov, dict):
                continue
            pt = self._oversight_open(ov)
            if pt is None:
                continue
            try:
                obj = json.loads(pt)
            except Exception:
                continue
            f = self._match_delivery_file(obj, entry)
            if f is None:
                continue
            if f.get("data_b64"):
                resolved = {"mode": "inline", "ov": ov}
            elif f.get("blob_id"):
                resolved = {"mode": "blob", "descriptor": f}
            if resolved is not None:
                break
        if resolved is not None or seen_delivery:
            self._library_src[lid] = resolved
            while len(self._library_src) > 1024:  # FIFO cap
                self._library_src.pop(next(iter(self._library_src)))
        return resolved

    def _library_bytes(self, entry, src):
        """Materialise a library download: returns (data, filename,
        mime) with sha256/size verified against the library index,
        or None when the bytes do not check out."""
        data = None
        mime = "application/octet-stream"
        if src["mode"] == "inline":
            pt = self._oversight_open(src["ov"])
            if pt is None:
                return None
            try:
                obj = json.loads(pt)
            except Exception:
                return None
            f = self._match_delivery_file(obj, entry)
            if f is None or not f.get("data_b64"):
                return None
            try:
                data = base64.b64decode(f["data_b64"])
            except Exception:
                return None
            mime = f.get("mime") or mime
        else:
            desc = src["descriptor"]
            data = self._blob_descriptor_bytes(desc)
            if data is None:
                return None
            mime = desc.get("mime") or mime
        sha = entry.get("sha256") or ""
        if sha and hashlib.sha256(data).hexdigest() != sha:
            return None
        size = int(entry.get("size") or 0)
        if size and len(data) != size:
            return None
        return data, entry.get("filename") or "download", mime

    @staticmethod
    def _vault_downloadable(desc) -> bool:
        """A vault entry is downloadable exactly when its stored
        descriptor carries the file-key oversight wrap + blob
        coordinates (every current vault put attaches one)."""
        return isinstance(desc, dict) \
            and isinstance(desc.get("oversight"), dict) \
            and bool(desc.get("blob_nonce")) and bool(desc.get("blob_id"))

    def _vault_bytes(self, entry):
        """Materialise a vault download from the entry's stored
        descriptor: (data, filename, mime), sha256/size verified
        against the vault index, or None."""
        desc = entry.get("descriptor") or {}
        data = self._blob_descriptor_bytes(desc)
        if data is None:
            return None
        sha = entry.get("sha256") or desc.get("sha256") or ""
        if sha and hashlib.sha256(data).hexdigest() != sha:
            return None
        size = int(entry.get("size") or desc.get("size") or 0)
        if size and len(data) != size:
            return None
        return data, entry.get("name") or desc.get("name") or "download", \
            desc.get("mime") or "application/octet-stream"

    def _open_into(self, item: dict, ov, content_envelope) -> bool:
        """Open one payload item's oversight wrap into display
        fields (text/title/content_kind/file_name/blob). Returns
        True only when the plaintext parsed as a valid content
        object; otherwise the item is left untouched (the caller
        marks it sealed) — raw key bytes never surface as text."""
        pt = self._oversight_open(ov, content_envelope)
        if pt is None:
            return False
        fields = self._content_fields(pt)
        if fields is None:
            return False
        item["text"] = fields["text"]
        item["content_kind"] = fields["content_kind"]
        if fields["file_name"]:
            item["file_name"] = fields["file_name"]
        if fields["title"]:
            item["title"] = fields["title"]
        item["sealed"] = False
        self._register_blob(item, fields["obj"])
        return True

    _CONTENT_KINDS = ("message", "group_message", "channel_message")
    _WORK_KINDS = ("work_assigned", "work_delivered")

    def _serve_data(self) -> dict:
        """The dashboard payload. Items carrying an `oversight` wrap
        (conversation items, activity rows) are opened HERE,
        server-side; plaintext rides only inside the authenticated
        operator payload (/api/status, /api/stream) and the wrap is
        stripped so ciphertext is never echoed onward. Group/channel
        items combine their wrap (a content-key wrap) with the
        persisted content envelope the relay stored on the audit
        row. Without a configured key — or when the plaintext does
        not parse as content — items stay honestly sealed."""
        data = self.relay._dashboard_data()
        data["oversight_enabled"] = self._oversight is not None
        audit_ov = {}
        rows = self._targeted_audit_rows(data)
        for r in rows:
            if isinstance(r, dict) and isinstance(r.get("oversight"), dict):
                audit_ov[(r.get("ref_id") or r.get("work_id") or "",
                          r.get("ts"), r.get("from"))] = r["oversight"]
        for c in data.get("conversations", []):
            for item in c.get("items", []):
                ov = item.pop("oversight", None)
                cenv = item.pop("content_envelope", None)
                if ov is None:
                    ov = audit_ov.get((item.get("id", ""), item.get("ts"),
                                       item.get("from")))
                kind = item.get("kind")
                if kind in self._CONTENT_KINDS \
                        or kind in self._WORK_KINDS:
                    if not self._open_into(item, ov, cenv):
                        item["sealed"] = True
                elif ov is not None:
                    self._open_into(item, ov, cenv)
        for row in data.get("activity", []):
            ov = row.pop("oversight", None)
            cenv = row.pop("content_envelope", None)
            if ov is None:
                continue
            if row.get("kind") in self._CONTENT_KINDS \
                    or row.get("kind") in self._WORK_KINDS:
                if not self._open_into(row, ov, cenv):
                    row["sealed"] = True
            else:
                self._open_into(row, ov, cenv)
        # Owner downloads (v1.1.2): annotate Library + Vault items
        # with a download_url when their oversight wrap chain
        # resolves, else an honest not-downloadable state. Sources
        # (wraps, descriptors) stay server-side — the payload gains
        # only the URL or the state, never wraps, keys or bytes.
        for e in data.get("library", []):
            if self._library_source(e, rows) is not None:
                e["download_url"] = f"/api/library/{e['id']}/download"
            else:
                e["not_downloadable"] = True
                e["download_note"] = \
                    "sealed before owner oversight"
        for v in data.get("vault", []):
            desc = v.pop("descriptor", None)
            v.pop("blob_id", None)
            if self._vault_downloadable(desc) \
                    and self._oversight_open_key(
                        desc.get("oversight")) is not None:
                v["download_url"] = f"/api/vault/{v['id']}/download"
            else:
                v["not_downloadable"] = True
                v["download_note"] = \
                    "sealed before owner oversight"
        return data

    # -- auth ------------------------------------------------------------------
    def _rate_limited(self, ip: str) -> bool:
        now = time.time()
        with self._lock:
            recent = [t for t in self._failures.get(ip, [])
                      if now - t < FAILURE_WINDOW]
            self._failures[ip] = recent
        return len(recent) >= MAX_FAILURES

    def _record_failure(self, ip: str) -> None:
        with self._lock:
            self._failures.setdefault(ip, []).append(time.time())

    # -- handler ------------------------------------------------------------------
    def _make_handler(self):
        dash = self

        class Handler(BaseHTTPRequestHandler):
            protocol_version = "HTTP/1.1"

            def log_message(self, *args):  # keep logs clean
                pass

            def _cookie_token(self) -> str:
                for part in self.headers.get("Cookie", "").split(";"):
                    part = part.strip()
                    if part.startswith(COOKIE + "="):
                        return part[len(COOKIE) + 1:]
                return ""

            def _authed(self) -> bool:
                token = self._cookie_token()
                return bool(token) and \
                    dash.relay.store.session_valid(_hash(token))

            def _send(self, code, body, ctype="text/html; charset=utf-8",
                      extra=None):
                data = body.encode() if isinstance(body, str) else body
                self.send_response(code)
                self.send_header("Content-Type", ctype)
                self.send_header("Content-Length", str(len(data)))
                for k, v in (extra or {}).items():
                    self.send_header(k, v)
                self.end_headers()
                self.wfile.write(data)

            def do_GET(self):
                path = urllib.parse.urlparse(self.path).path
                if path == "/api/status":
                    if not self._authed():
                        return self._send(401, '{"error":"login required"}',
                                          "application/json")
                    return self._send(
                        200, dash._snapshot_json(),
                        "application/json")
                if path.startswith("/api/blob/"):
                    # Oversight file rendering: bytes are decrypted
                    # server-side (key unwrapped while opening the
                    # message in _serve_data) and served ONLY to the
                    # authenticated operator session. Images/videos
                    # render inline; everything else downloads.
                    if not self._authed():
                        return self._send(401, '{"error":"login required"}',
                                          "application/json")
                    blob_id = urllib.parse.unquote(
                        path[len("/api/blob/"):])
                    got = dash._blob_bytes(blob_id)
                    if got is None:
                        return self._send(
                            404, '{"error":"blob unavailable"}',
                            "application/json")
                    data, entry = got
                    mime = entry["mime"] or "application/octet-stream"
                    inline = mime.startswith(("image/", "video/")) \
                        or entry["kind"] in ("image", "video")
                    if inline:
                        disp = "inline"
                    else:
                        fname = (entry["name"] or "file").replace(
                            '"', "").replace("\n", "")
                        disp = f'attachment; filename="{fname}"'
                    return self._send(200, data, mime, extra={
                        "Content-Disposition": disp,
                        "Cache-Control": "private, no-store"})
                if (path.startswith("/api/library/")
                        and path.endswith("/download")) or \
                        (path.startswith("/api/vault/")
                         and path.endswith("/download")):
                    # Owner downloads (v1.1.2): the operator
                    # personally downloads deliverables (Library) and
                    # shared files (Vault). Bytes are resolved
                    # server-side through the item's oversight wrap
                    # chain and served as an attachment with the
                    # original filename — only to the authenticated
                    # operator session. Unresolvable (legacy,
                    # pre-oversight) items refuse cleanly with 404.
                    if not self._authed():
                        return self._send(401, '{"error":"login required"}',
                                          "application/json")
                    is_vault = path.startswith("/api/vault/")
                    prefix = "/api/vault/" if is_vault \
                        else "/api/library/"
                    item_id = urllib.parse.unquote(
                        path[len(prefix):-len("/download")]).strip("/")
                    got = None
                    if is_vault:
                        entry = dash.relay.store.vault_entry(item_id)
                        if entry is not None:
                            got = dash._vault_bytes(entry)
                    else:
                        entry = dash.relay.store.library_entry(item_id)
                        if entry is not None:
                            src = dash._library_source(entry)
                            if src is not None:
                                got = dash._library_bytes(entry, src)
                    if got is None:
                        return self._send(
                            404, '{"error":"not_downloadable",'
                            '"detail":"sealed before owner oversight"}',
                            "application/json")
                    data, fname, mime = got
                    fname = (fname or "download").replace(
                        '"', "").replace("\n", "")
                    return self._send(200, data, mime, extra={
                        "Content-Disposition":
                            f'attachment; filename="{fname}"',
                        "Cache-Control": "private, no-store"})
                if path == "/api/stream":
                    if not self._authed():
                        return self._send(401, '{"error":"login required"}',
                                          "application/json")
                    return self._stream()
                if path in ("/", "/dashboard"):
                    if self._authed():
                        return self._send(200, DASHBOARD_HTML)
                    return self._send(200, LOGIN_HTML)
                return self._send(404, "not found", "text/plain")

            def do_POST(self):
                path = urllib.parse.urlparse(self.path).path
                length = int(self.headers.get("Content-Length") or 0)
                body = self.rfile.read(length).decode() if length else ""
                form = urllib.parse.parse_qs(body)
                if path == "/login":
                    ip = self.client_address[0]
                    if dash._rate_limited(ip):
                        return self._send(
                            429, "Too many failed attempts — try again later.",
                            "text/plain")
                    pw = (form.get("password") or [""])[0]
                    if not hmac.compare_digest(pw, dash._password):
                        dash._record_failure(ip)
                        return self._send(401, LOGIN_HTML.replace(
                            "<!--error-->", '<p class="err">Wrong password.</p>'))
                    token = secrets.token_urlsafe(32)
                    dash.relay.store.create_session(
                        _hash(token), int(time.time()) + SESSION_TTL)
                    secure = "; Secure" if self.headers.get(
                        "X-Forwarded-Proto") == "https" else ""
                    cookie = (f"{COOKIE}={token}; HttpOnly; SameSite=Lax;"
                              f" Path=/; Max-Age={SESSION_TTL}{secure}")
                    return self._send(302, "", extra={
                        "Location": "/", "Set-Cookie": cookie})
                if path == "/logout":
                    token = self._cookie_token()
                    if token:
                        dash.relay.store.revoke_session(_hash(token))
                    return self._send(302, "", extra={
                        "Location": "/",
                        "Set-Cookie": f"{COOKIE}=; HttpOnly; Path=/; Max-Age=0"})
                return self._send(404, "not found", "text/plain")

            def _stream(self):
                self.send_response(200)
                self.send_header("Content-Type", "text/event-stream")
                self.send_header("Cache-Control", "no-cache")
                self.send_header("Connection", "keep-alive")
                self.end_headers()
                q: queue.Queue = queue.Queue(maxsize=50)
                with dash._lock:
                    dash._subscribers.add(q)
                try:
                    self.wfile.write(b"data: " + dash._snapshot_json(
                        ).encode() + b"\n\n")
                    self.wfile.flush()
                    while True:
                        try:
                            snap = q.get(timeout=15)
                            self.wfile.write(b"data: " + snap.encode()
                                             + b"\n\n")
                        except queue.Empty:
                            self.wfile.write(b": heartbeat\n\n")
                        self.wfile.flush()
                except (BrokenPipeError, ConnectionResetError):
                    pass
                finally:
                    with dash._lock:
                        dash._subscribers.discard(q)

        return Handler


